ROOT=Path(__file__).resolve().parents[1]
font='/System/Library/Fonts/Supplemental/'
pdfmetrics.registerFont(TTFont('ArialR',font+'Arial.ttf'))
pdfmetrics.registerFont(TTFont('ArialB',font+'Arial Bold.ttf'))
pdfmetrics.registerFontFamily('ArialR',normal='ArialR',bold='ArialB')
W,H=595.28,841.89
INK=HexColor('#29332F');MUTED=HexColor('#647068'); ORANGE=HexColor('#D97627');PAPER=HexColor('#F6F5EF');LINE=HexColor('#DADDD3')
OUT=ROOT/'output/pdf/rubezh-13-design-v0.3.pdf'
c=canvas.Canvas(str(OUT),pagesize=(W,H));c.setTitle('Рубеж / 13 - дизайн-док MVP v0.3');c.setAuthor('Рабочий документ проекта')
styles={
 'body':ParagraphStyle('body',fontName='ArialR',fontSize=10.3,leading=15,textColor=INK,spaceAfter=7),
 'small':ParagraphStyle('small',fontName='ArialR',fontSize=8.7,leading=12,textColor=MUTED),
 'h2':ParagraphStyle('h2',fontName='ArialB',fontSize=14,leading=19,textColor=INK),
 'table':ParagraphStyle('table',fontName='ArialR',fontSize=9.1,leading=12.5,textColor=INK),
}
y=0;page=0

def para(text,style='body',x=44,width=W-88,gap=9):
 global y
 p=Paragraph(text,styles[style]);w,h=p.wrap(width,H)
 assert y-h>53,(page,text[:50],y,h)
 p.drawOn(c,x,y-h);y-=h+gap

def begin(title,kicker):
 global y,page
 page+=1
 c.setFillColor(PAPER);c.rect(0,0,W,H,fill=1,stroke=0)
 c.setFillColor(ORANGE);c.rect(44,H-42,30,4,fill=1,stroke=0)
 c.setFont('ArialB',9);c.setFillColor(MUTED);c.drawString(85,H-41,'РУБЕЖ / 13     •     ДИЗАЙН-ДОК MVP')
 c.setFont('ArialR',8);c.drawRightString(W-44,H-41,'v0.3 / 25.09.2026')
 c.setStrokeColor(LINE);c.line(44,43,W-44,43)
 c.setFont('ArialR',8);c.drawString(44,29,'Рабочая версия для обсуждения и правок')
 c.drawRightString(W-44,29,f'{page:02d} / 07')
 y=H-81
 para(kicker.upper(),'small',gap=10)
 c.setFillColor(INK);c.setFont('ArialB',28);c.drawString(44,y-27,title);y-=49

def section(title,text):
 para(title,'h2',gap=6);para(text)

def table(rows,widths):
 global y
 rows=[[Paragraph(str(v),styles['table']) for v in row] for row in rows]
 t=Table(rows,colWidths=widths,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor('#E6E8DF')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8),('LINEBELOW',(0,0),(-1,-1),.5,LINE)]))
 w,h=t.wrap(W-88,H);assert y-h>60,(page,y,h);t.drawOn(c,44,y-h);y-=h+14

def notes(lines=3):
 global y
 y-=7;para('ЗАМЕТКИ / ПРАВКИ','small',gap=3)
 for _ in range(lines):
  y-=22;c.setStrokeColor(LINE);c.line(44,y,W-44,y)

def end():c.showPage()


begin('Рубеж / 13','01 / Дизайн прототипа · v0.3')
para('Пять рубежей. Один командир.','h2')
para('Трёхмерный roguelite о защите базы: солдат получает оружие, занимает технику, отражает волны и возвращается в хаб с валютой. Эта версия заменяет PDF v0.2 и включает новый интерфейс, шесть комнат, щитоносца и четыре ветки прокачки до 20 уровней.')
c.drawImage(str(ROOT/'screenshots/room_3.png'),44,y-260,width=507,height=260,preserveAspectRatio=True,anchor='c',mask='auto');y-=282
section('Цель ощущений','Средняя сложность после знакомства с типами врагов; высокая прокачка должна заметно прощать ошибки. Сохраняем медленные выстрелы, перебежки и необходимость менять позицию. Максимум прокачки облегчает прохождение, но не гарантирует победу при бездействии.')
section('Статус чисел','Правила пользователя реализованы. Числа в документе - начальный баланс для плейтеста. Проверки механик и расчётные показатели отделены от автоматических боёв на странице 7.')
section('Платформа и стиль','Godot, горизонтальный экран, клавиатура и мультитач. Простые объёмные модели Blender, приглушённые оттенки комнат. Ортографическая камера повёрнута вправо на 10°. Нативная сборка на iPhone ещё не проверена.')
end()
begin('Комнаты и волны','02 / Прогрессия вылазки')
table([['Этап','Поле','Введение'],['1','13×13','Солдаты, гранатомётчики, затем багги'],['2','15×15','Дроны и щитоносцы; в конце БТР'],['3','17×17','Гранатные турели; в конце танк'],['4','18×18','Смешанная броня и поддержка'],['5','19×19','Все типы; последняя волна - 7 танков'],['6','20×20','Босс 4×4, редкая поддержка, малые укрытия']],[50,70,387])
section('Ритм','В обычной комнате три волны. Перед каждой отсчёт 3,75 с, после каждой выбор 1 из 3 улучшений. Между комнатами сохраняются сердца, бонусы и занятая машина; новая база имеет полный запас HP. Оставленные машины и турели не переносятся.')
section('Сочетания вместо чистого случайного набора','Состав собирается парами: багги + дрон, БТР + гранатомётчик, щитоносец + солдат, турель + багги, танк + поддержка. Цена: солдат 1; багги, дрон, гранатомётчик 2; щитоносец и БТР 3; турель 4; танк 5. Бюджет волны фиксирован.')
table([['Комната','Бюджеты трёх волн'],['1 / 2','5, 7, 9 / 10, 12, 14'],['3 / 4','17, 19, 22 / 22, 26, 31'],['5','27, 34, 35']],[120,387])
para('Ограничения: до 2 щитоносцев и дронов, до 3 гранатомётчиков; турелей до 1 в комнате 3 и до 2 позднее. Новая техника гарантированно вводится в третьей волне соответствующей комнаты.','small')
end()
begin('Поле и управление','03 / Читаемость и движение')
section('Генерация','Пять обычных карт генерируются заново. Бетон перекрывает три соседние центральные колонки на разной глубине. Дополнительные блоки стоят на флангах и внизу, прерывая горизонтальный прострел у базы. Все проходы связаны без разрушения кирпича. Крайние маршруты дронов открыты.')
section('Материалы','Кирпич: 3 HP, блокирует движение и пули. Бетон: неразрушим. Маскировочная сетка: пропускает движение и огонь, скрывает метки врагов и мешает прицеливанию ИИ. Финальная арена открытая, четыре отдельных укрытия по 2-3 клетки.')
section('Маршруты','Обычные враги получают две случайные промежуточные точки перед атакой базы. Солдат чередует перебежки на 1 и 2 клетки, БТР и гранатомётчик проходят по 2, танк и босс по 1 с длинными паузами. Дрон и багги едут без пауз, кроме препятствий и поворотов.')
table([['Действие','Клавиатура','Сенсор'],['Движение','WASD / стрелки','Крестовина'],['Стрелять','Удерживать пробел','Кнопка огня'],['Техника / станок','E рядом','Контекстная кнопка'],['Пауза / закрыть','Esc','Кнопка / крестик']],[130,170,207])
section('Огонь и интерфейс','Стрейфа нет. Во время поворота стрельба блокируется, затем продолжается при удержании. Здоровье без цифр: сегменты с иконками сердца и базы в HUD; над бойцами, техникой и турелями - полоски. Цвет от зелёного через жёлтый к красному. Слева оружие; справа этап, волна и значки врагов: тёмные ожидают, охра на поле, светлые выбыли. Звезда обозначает босса.')
section('Хаб','Стрельба пешком и из учебного танка, чучело показывает урон. Прокачка открывается только по E у станка. Текст сокращён; окно закрывается E, Esc или крестиком.')
end()
begin('Противники и оружие','04 / Окна атаки и защиты')
table([['Тип','HP','Атака / особенность'],['Солдат','2','1 урона, интервал 1,45 с'],['Щитоносец','4','1 урона, 1,8 с; фронтальный щит с паузами'],['Гранатомётчик','3','Граната 1 урона каждые 3,8 с, полёт 2 с'],['Багги','4','0,25 урона, 0,38 с; пули 20 клеток/с'],['БТР','5','1 урона, 0,8 с'],['Танк','9','3 урона, 1,25 с'],['Дрон','1','Бомба: 3 урона через 1,35 с'],['Турель врага','5','Граната в базу: 1 урона, 7,5 с; первый выстрел через 4 с'],['Босс','100','Прицельный снаряд 2 урона раз в 2,2 с; круг из 16 шаров']],[105,40,362])
section('Щитоносец','Со второй комнаты. Видит игрока в радиусе 7 клеток, поднимает щит за 0,55 с. Защита действует 1,1 с, затем 2,2 с перезарядки. Во время поднятия и перезарядки уязвим. Активный щит блокирует только пули спереди; бок, тыл и взрывы обходят защиту. Со щитом не стреляет и не доворачивается за игроком.')
section('Гранаты и босс','Гранаты движутся по баллистической дуге над стенами, точка падения отмечена. Радиус 1,15 клетки; турельная граната летит 3 с. Босс предупреждает круговой залп за 1,15 с, затем делает перерыв 11 с. В финале базы нет.')
para('Оружие игрока до улучшений: винтовка 1 / 0,6 с; ПП 1 / 0,32 с; тяжёлая винтовка 3 / 1,25 с. Урон записан первым.','small')
end()
begin('Бонусы и техника','05 / Риск выхода от базы')
section('Случайный дроп','За убитого обычного врага независимо проверяются два события: обычный бонус 12% и сердце 6%. Ветка «Дроп» добавляет каждому шансу по 0,5 процентного пункта за уровень. Максимум: бонус 22%, сердце 16%. Оба предмета могут выпасть одновременно. Самоподрыв дрона не считается убийством.')
section('Размещение и лечение','Предметы появляются на свободных клетках верхней половины, чтобы за ними нужно было выходить от базы. Сердце восстанавливает 1 HP солдата, не выше максимума; работает и когда солдат внутри машины, броню не чинит. Сердца могут выпадать и из подкреплений босса, обычные бонусы - только в комнатах защиты.')
section('Что дают бонусы','Ремонт базы: +2 HP. Стены: восстановить или укрепить щиток базы. Техника: исправная машина появляется у базы без таймера посадки. Турель: гранатная установка слева или справа базы, максимум две; разрушенное место можно занять снова. Турели доступны с третьей комнаты.')
section('Гарантированные поставки','В конце комнаты 1 открывается багги, комнаты 2 - БТР, комнаты 3 - танк, одновременно с бонусом поставки. В первой волне комнат 3-5 есть бонус турели. Эти гарантии сохраняют доступ к новым механикам независимо от случайного дропа.')
section('Союзная турель','5 HP, граната раз в 5,5 с, радиус поиска цели 12 клеток. Базовый урон 1, максимум мета-прокачки 1,5. Вражеские пули и бомбы её уничтожают. Союзные гранаты не повреждают игрока и базу; взрывы бомб и корпусов опасны всем.')
section('Временные улучшения','После волны: урон +0,5 (багги +0,125), интервал огня −15%, скорость +12%, сердце +1 к максимуму с лечением, смена оружия или перехват +10 п.п. Перехват стартует с 70%, предел 95%. При успехе своя пуля переживает столкновение.')
end()
begin('Прокачка до 20','06 / Экономика и полный сброс')
table([['Ветка','За уровень','На уровне 20'],['Здоровье','+1 HP солдату; +1 HP базе каждые 5 уровней','Солдат 23 HP; база 9 HP'],['Урон','+0,25; багги получает четверть этой прибавки','Винтовка 6; тяжёлая / танк 8; багги 1,5'],['Дроп','+0,5 п.п. к каждому шансу','Сердце 16%; бонус 22%'],['Турели','+0,025 урона гранаты','1,5 урона вместо 1']],[92,235,180])
section('Стоимость','Все четыре ветки имеют по 20 уровней. Следующая покупка стоит 12 + 4 × текущий уровень: от 12 до 88 сплава. Одна полная ветка стоит 1000, здоровье + урон - 2000, весь профиль - 4000. Лимит проверяется в логике покупок, а не только в интерфейсе.')
section('Темп накопления','Полная вылазка содержит около 335 сплава при убийстве всего состава и победе, без учёта подкреплений и ушедших в самоподрыв дронов. Это примерно 6 полных побед на две основные ветки или 12 на весь профиль. Фактически дольше из-за поражений; добыча при поражении сохраняется. Первые покупки дешёвые: 12, 16, 20...')
section('Почему максимум облегчает игру','Без временных бонусов винтовка убивает танк за 9 попаданий на нулевом уровне, за 2 на максимальном. Босс - за 100 или 17 попаданий. Это 59,4 с и 9,6 с между первым и последним выстрелом при идеальной непрерывной стрельбе. У игрока также больше сердец и запас прочности базы.')
section('Сохранение и обнуление','Старые уровни и валюта сохраняются при переходе на новую версию, новые ветки начинают с нуля. Кнопка «Обнулить профиль» немедленно обнуляет все четыре ветки и весь сплав; возврата валюты нет. Сброс сохраняется на диске. Автоматически профиль пользователя не сбрасывается.')
end()
begin('Проверка баланса','07 / Результаты и границы проверки')
section('Боевой эксперимент','Три фиксированные карты: seed 42, 84, 126. Простой бот идёт к ближайшему врагу и стреляет, без повышенного здоровья. Выбирает здоровье в средней волне и урон в остальных. Не умеет осмысленно уклоняться, использовать технику или собирать бонусы. Поэтому это сравнение профилей, не прогноз процента побед человека.')
table([['Уровни всех веток','Результат на трёх картах'],['0','0/3 побед; поражение в комнатах 1, 1, 2'],['10','0/3 побед; поражение в комнатах 4, 4, 5'],['20','3/3 побед; бой примерно 6,2-6,7 мин, осталось 4,5-10,75 HP']],[150,357])
section('Что изменено после эксперимента','Первый прогон максимума дал 2/3 побед: одна база погибла, пока солдат имел запас здоровья. Добавлены +1 HP базе каждые пять уровней здоровья и более редкий огонь вражеских турелей. Финальный прогон дал 3/3. Выборка мала; средняя сложность для живого игрока остаётся целью плейтеста.')
section('Проверки механик','Покупки всех 80 уровней, пределы и цена 4000; сохранение новых веток; полный сброс с обнулением валюты; щит спереди/сбоку/сзади и его фазы; сердца и предел HP; урон союзной турели; 10 000 бросков дропа. Также проверяются 500 карт, сочетания волн, хаб, сенсорный ввод и проход всех комнат.')
section('Следующий плейтест','На чистом профиле: понятен ли первый гранатомётчик, есть ли время обойти щит, хватает ли сердец. На уровне 10: можно ли пройти при разумном использовании техники. На максимуме: ощущается ли преимущество без полного исчезновения угрозы базе. Для оценки нужны живые прогоны; бессмертный бот для этой оценки не используется.')
notes(2)
